public class SaveClaim {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            @Val ClaimInput input, ServerHttpConnection connection, ClaimRepository repository,
            SheetRepository sheets, PeriodRepository periods, PersonRepository people, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        // Only a draft can be edited: to change an open claim, void it and add a new one.
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be edited");
        }
        String holder = repository.lockedBy(id, cid);
        if (holder != null && !holder.equals(by)) {
            throw new BadRequestException("the claim is being edited by " + holder);
        }
        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
        PeriodGuard.open(periods, id, date);
        people.claimAllowed(id, found.personId(), date);
        input.checkCorrection(repository, id, found.personId());
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.update(id, cid, input.amount(), date, input.note(), input.corrects())) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        repository.unlock(id, cid, by);
        long pid = found.personId();
        Claim saved = new Claim(cid, pid, ClaimRepository.money(input.amount()), date.toString(), input.note(),
                found.status(), found.number(), found.due(), found.openedBy(), found.stated(), found.statedDue(), input.corrects(),
                found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry());
        audit.record("CLAIM_EDITED sheet=" + id + " by=" + by + " person=" + repository.personName(id, pid)
                + " amount=" + saved.amount() + " date=" + saved.date() + Claim.auditNumber(saved.number()));
        rollup.record(id, by, before);
        claim.set(saved);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A steward re-dates an OPEN or PENDING claim: neither its old nor its new date may be in a closed period, nor the
 *  new date after its person's retirement. Its due-by stays as it was fixed and a figure its statement bound stays
 *  bound; its period follows the new date, and under period numbering a claim whose period changes takes the next
 *  number of its new period's sequence (its old one is never reused). Every check is made before anything is
 *  written, so a refusal writes nothing to the store or the audit. */
final class ClaimRedate {
    private ClaimRedate() {
    }

    static Claim apply(String id, long cid, String newDate, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup)
            throws BadRequestException {
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can re-date a claim");
        }
        if (!found.open()) {
            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
        }
        String raw = newDate == null ? "" : newDate.trim();
        if (raw.isEmpty()) {
            throw new BadRequestException("give the claim's new date");
        }
        LocalDate date;
        try {
            date = LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("the new date must be yyyy-mm-dd");
        }
        LocalDate old = LocalDate.parse(found.date());
        PeriodGuard.open(periods, id, old);
        PeriodGuard.open(periods, id, date);
        people.claimAllowed(id, found.personId(), date);
        Rollup.Snapshot before = rollup.take(id);
        boolean moved = !repository.sequenceKey(id, old).equals(repository.sequenceKey(id, date));
        if (!repository.redate(id, cid, date)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
        }
        String number = found.number();
        if (moved && repository.numbersPerPeriod(id)) {
            number = repository.numberInPeriod(id, cid, date);
        }
        audit.record("CLAIM_REDATED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + found.amount() + " date=" + date + Claim.auditNumber(number)
                + " old=" + old + " new=" + date);
        rollup.record(id, by, before);
        return repository.find(id, cid);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** Split an amount (more than 0.00, less than the claim's amount) off an OPEN claim not deferred nor in a closed
 *  period, by a user whose role may open a claim: the claim keeps the rest and is unbound from its last statement;
 *  a new OPEN claim with the split-off amount, the same date and note and the next number, opened by the user, with
 *  its due-by fixed now and the original's number as split-from, is listed under the person. Every check is made
 *  before anything is written, so a refusal writes nothing to the store or the audit. Answers the new claim. */
final class ClaimSplit {
    private ClaimSplit() {
    }

    static Claim apply(String id, long cid, String amount, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.status().equals("OPEN")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be split");
        }
        if (found.deferred()) {
            throw new BadRequestException("a deferred claim cannot be split");
        }
        BigDecimal part = ClaimInput.amount(amount == null ? "" : amount.trim());
        if (part.signum() <= 0 || part.compareTo(new BigDecimal(found.amount())) >= 0) {
            throw new BadRequestException("the amount split off must be more than 0.00 and less than the claim's amount");
        }
        LocalDate date = LocalDate.parse(found.date());
        PeriodGuard.open(periods, id, date);
        if (!settings.allows(id, "open", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot open a claim, so cannot split one");
        }
        Rollup.Snapshot before = rollup.take(id);
        Long nid = repository.split(id, found, part, by);
        if (nid == null) {
            throw new BadRequestException("a " + found.status() + " claim cannot be split");
        }
        String number = repository.numbersPerPeriod(id) ? repository.numberInPeriod(id, nid, date)
                : repository.number(id, nid);
        repository.log(id, nid, by);
        Claim kept = repository.find(id, cid);
        Claim added = repository.find(id, nid);
        String person = repository.personName(id, found.personId());
        audit.record("CLAIM_SPLIT sheet=" + id + " by=" + by + " person=" + person + " amount=" + kept.amount()
                + " date=" + kept.date() + Claim.auditNumber(kept.number()) + " into=" + number);
        audit.record("CLAIM_OPENED sheet=" + id + " by=" + by + " person=" + person + " amount=" + added.amount()
                + " date=" + added.date() + Claim.auditNumber(number));
        rollup.record(id, by, before);
        return added;
    }
}
